  "core-2ed:good-time-management": { name:"Boa Gestão do Tempo", description:"Ao realizar uma ação prolongada, reduz pela metade o tempo de cada intervalo, desde que disponha das ferramentas e condições adequadas para organizar o trabalho.", page:45 },
